#version 460
#extension GL_GOOGLE_include_directive : require
#include "pelican_sets.glsl"
#include "pelican_view.glsl"

// GB-3 A: the initial spectrum h0(k) of a Tessendorf ocean (Phillips), drawn
// into an N x N image (this pass's own, Fixed 256 x 256, R32G32B32A32_SFLOAT).
// A pure function of the pixel: the pass runs once (PS-1s, Schedule = Once)
// into a Persistent image. rgba = (h0(k), conj(h0(-k))).

layout(location = 0) in vec2 inUV;
layout(location = 0) out vec4 outColor;

const float PI = 3.14159265358979;
const float G = 9.81;
const float PATCH = 64.0;          // metres the patch covers
const float AMPLITUDE = 0.00003;   // Phillips A (about 0.4 m rms)
const vec2 WIND = vec2(1.0, 0.35);
const float WIND_SPEED = 9.0;      // m/s

uint hash(uint x) {
    x ^= x >> 16; x *= 0x7feb352dU;
    x ^= x >> 15; x *= 0x846ca68bU;
    x ^= x >> 16;
    return x;
}
float uniform01(uint seed) { return (float(hash(seed) & 0x00ffffffU) + 0.5) / 16777216.0; }
vec2 gaussian(uvec2 p) {
    uint seed = hash(p.x * 1973U + p.y * 9277U + 26699U);
    float u1 = uniform01(seed);
    float u2 = uniform01(seed ^ 0x9e3779b9U);
    float r = sqrt(-2.0 * log(u1));
    return r * vec2(cos(2.0 * PI * u2), sin(2.0 * PI * u2));
}
float phillips(vec2 k) {
    float kl = length(k);
    if (kl < 1e-4) return 0.0;
    float L = WIND_SPEED * WIND_SPEED / G;
    float kw = dot(k / kl, normalize(WIND));
    float damp = 0.001 * L;
    return AMPLITUDE * exp(-1.0 / (kl * L * kl * L)) / (kl * kl * kl * kl) * kw * kw *
           exp(-kl * kl * damp * damp);
}
vec2 h0At(ivec2 p, int n) {
    vec2 k = 2.0 * PI * (vec2(p) - vec2(n / 2)) / PATCH;
    return gaussian(uvec2(p)) * sqrt(phillips(k) * 0.5);
}

void main() {
    const int n = 256;
    ivec2 p = ivec2(gl_FragCoord.xy);
    vec2 a = h0At(p, n);
    vec2 b = h0At((ivec2(n) - p) % ivec2(n), n);
    outColor = vec4(a, b.x, -b.y);
}

#version 460
#extension GL_GOOGLE_include_directive : require
#include "pelican_sets.glsl"
#include "pelican_frame.glsl"

// GB-3 A: h(k, t) from h0 (input 0) at the scene's time (the frame's
// time_delta.x: it stops while paused), packed for one complex IFFT per pair:
// rg = h + i*Dx, ba = Dz + i*0 (each real after the transform).

layout(location = 0) in vec2 inUV;
layout(location = 0) out vec4 outColor;

PELICAN_DECLARE_INPUT_0(h0);

#if PELICAN_INPUT_0_LAYERED
#define FETCH0(p) texelFetch(h0, ivec3((p), 0), 0)
#else
#define FETCH0(p) texelFetch(h0, (p), 0)
#endif

const float PI = 3.14159265358979;
const float G = 9.81;
const float PATCH = 64.0;

vec2 cmul(vec2 a, vec2 b) { return vec2(a.x * b.x - a.y * b.y, a.x * b.y + a.y * b.x); }

void main() {
    const int n = 256;
    ivec2 p = ivec2(gl_FragCoord.xy);
    float t = pelicanFrame.time_delta.x;
    vec2 k = 2.0 * PI * (vec2(p) - vec2(n / 2)) / PATCH;
    float kl = max(length(k), 1e-4);
    float w = sqrt(G * kl);
    vec4 s = FETCH0(p);
    vec2 e = vec2(cos(w * t), sin(w * t));
    vec2 h = cmul(s.xy, e) + cmul(s.zw, vec2(e.x, -e.y));
    vec2 dx = vec2(h.y, -h.x) * (k.x / kl);   // -i k/|k| h
    vec2 dz = vec2(h.y, -h.x) * (k.y / kl);
    outColor = vec4(h + vec2(-dx.y, dx.x), dz);
}

#version 460
#extension GL_GOOGLE_include_directive : require
#include "pelican_sets.glsl"
#include "pelican_view.glsl"

// GB-3 A: the IFFT's result (input 0) to a displacement image: the (-1)^(x+y)
// of the centred spectrum and the choppiness. rgb = (dx, h, dz), a = 1.

layout(location = 0) in vec2 inUV;
layout(location = 0) out vec4 outColor;

PELICAN_DECLARE_INPUT_0(spatial);

#if PELICAN_INPUT_0_LAYERED
#define FETCH0(p) texelFetch(spatial, ivec3((p), 0), 0)
#else
#define FETCH0(p) texelFetch(spatial, (p), 0)
#endif

const float CHOPPY = 1.2;

void main() {
    ivec2 p = ivec2(gl_FragCoord.xy);
    vec4 v = FETCH0(p) * ((((p.x + p.y) & 1) == 0) ? 1.0 : -1.0);
    outColor = vec4(CHOPPY * v.y, v.x, CHOPPY * v.z, 1.0);
}

#version 460
#extension GL_GOOGLE_include_directive : require
#include "pelican_sets.glsl"
#include "pelican_frame.glsl"
#include "pelican_view.glsl"

// GB-3 A: the sea surface, drawn by a raster pass with no vertex buffer
// (draw.vertex_count = 6 * GRID * GRID: Grid 257 x 257 in its Pass fields,
// draw.instance_count = 2). Instance 0 is a GRID x GRID grid of quads on the
// plane y = SEA_LEVEL, displaced by the displacement image (input 0, read here
// in the vertex stage); the pass's depth image (D32_SFLOAT) puts the nearer
// waves in front. Instance 1 is the sky: its first triangle covers the screen
// on the far plane (depth 1, drawn where no wave is: depth_compare less_equal),
// its other vertices fall outside the screen.

PELICAN_DECLARE_INPUT_0(displacement);

#if PELICAN_INPUT_0_LAYERED
#define FETCH0(p) texelFetch(displacement, ivec3((p), 0), 0)
#else
#define FETCH0(p) texelFetch(displacement, (p), 0)
#endif

layout(location = 0) out vec3 outWorld;
layout(location = 1) out vec2 outPatch;
layout(location = 2) out float outSky;

const int GRID = 256;
const float PATCH = 64.0;        // metres one displacement tile covers
const float SEA_LEVEL = -2.0;
const vec2 EXTENT_X = vec2(-60.0, 60.0);
const vec2 EXTENT_Z = vec2(2.5, -140.0);  // ahead of the camera, which looks down -Z

// Bilinear, wrapping, by texel: the same in both stages.
vec3 displacementAt(vec2 world_xz) {
    vec2 t = world_xz / PATCH * 256.0 - 0.5;
    ivec2 i = ivec2(floor(t));
    vec2 f = t - vec2(i);
    ivec2 a = i & 255, b = (i + 1) & 255;
    vec3 d00 = FETCH0(ivec2(a.x, a.y)).xyz, d10 = FETCH0(ivec2(b.x, a.y)).xyz;
    vec3 d01 = FETCH0(ivec2(a.x, b.y)).xyz, d11 = FETCH0(ivec2(b.x, b.y)).xyz;
    return mix(mix(d00, d10, f.x), mix(d01, d11, f.x), f.y);
}

void main() {
    if (gl_InstanceIndex == 1) {
        int i = gl_VertexIndex < 3 ? gl_VertexIndex : 0;
        vec2 uv = vec2((i << 1) & 2, i & 2);
        gl_Position = gl_VertexIndex < 3 ? vec4(uv * 2.0 - 1.0, 1.0, 1.0) : vec4(2.0, 2.0, 2.0, 1.0);
        outWorld = vec3(uv, 0.0);
        outPatch = vec2(0.0);
        outSky = 1.0;
        return;
    }
    int quad = gl_VertexIndex / 6;
    int corner = gl_VertexIndex % 6;
    int row = quad / GRID;
    int column = quad % GRID;
    const ivec2 corners[6] = ivec2[6](ivec2(0, 0), ivec2(1, 0), ivec2(1, 1),
                                      ivec2(0, 0), ivec2(1, 1), ivec2(0, 1));
    ivec2 cell = ivec2(column, row) + corners[corner];
    vec2 s = vec2(cell) / float(GRID);
    // denser near the camera: z grows with the square of the row
    vec2 xz = vec2(mix(EXTENT_X.x, EXTENT_X.y, s.x), mix(EXTENT_Z.x, EXTENT_Z.y, s.y * s.y));
    vec3 d = displacementAt(xz);
    vec3 world = vec3(xz.x + d.x, SEA_LEVEL + d.y, xz.y + d.z);
    outWorld = world;
    outPatch = xz;
    outSky = 0.0;
    gl_Position = pelicanFrame.projection * pelicanFrame.view * vec4(world, 1.0);
}

#version 460
#extension GL_GOOGLE_include_directive : require
#include "pelican_sets.glsl"
#include "pelican_frame.glsl"
#include "pelican_view.glsl"

// GB-3 A: the sea's colour: a normal from the displacement image (input 0,
// central differences), Fresnel between the deep colour and the sky, and a
// sun highlight. The sky triangle (outSky = 1) is a gradient.

PELICAN_DECLARE_INPUT_0(displacement);

#if PELICAN_INPUT_0_LAYERED
#define FETCH0(p) texelFetch(displacement, ivec3((p), 0), 0)
#else
#define FETCH0(p) texelFetch(displacement, (p), 0)
#endif

layout(location = 0) in vec3 inWorld;
layout(location = 1) in vec2 inPatch;
layout(location = 2) in float inSky;
layout(location = 0) out vec4 outColor;

const float PATCH = 64.0;
const vec3 SUN = normalize(vec3(0.3, 0.45, -1.0));
const vec3 DEEP = vec3(0.01, 0.06, 0.10);

vec3 displacementAt(vec2 world_xz) {
    vec2 t = world_xz / PATCH * 256.0 - 0.5;
    ivec2 i = ivec2(floor(t));
    vec2 f = t - vec2(i);
    ivec2 a = i & 255, b = (i + 1) & 255;
    vec3 d00 = FETCH0(ivec2(a.x, a.y)).xyz, d10 = FETCH0(ivec2(b.x, a.y)).xyz;
    vec3 d01 = FETCH0(ivec2(a.x, b.y)).xyz, d11 = FETCH0(ivec2(b.x, b.y)).xyz;
    return mix(mix(d00, d10, f.x), mix(d01, d11, f.x), f.y);
}

vec3 sky(vec3 direction) {
    float up = clamp(direction.y, 0.0, 1.0);
    vec3 color = mix(vec3(0.72, 0.80, 0.88), vec3(0.20, 0.42, 0.75), pow(up, 0.5));
    return color + vec3(1.0, 0.9, 0.7) * pow(max(dot(direction, SUN), 0.0), 400.0) * 4.0;
}

void main() {
    if (inSky > 0.5) {
        vec2 ndc = inWorld.xy * 2.0 - 1.0;
        vec4 far = inverse(pelicanFrame.projection * pelicanFrame.view) * vec4(ndc, 1.0, 1.0);
        vec3 direction = normalize(far.xyz / far.w - pelicanFrame.camera_position.xyz);
        outColor = vec4(sky(direction), 1.0);
        return;
    }
    float e = PATCH / 256.0;
    vec3 px = vec3(e, 0.0, 0.0) + displacementAt(inPatch + vec2(e, 0.0)) -
              displacementAt(inPatch - vec2(e, 0.0)) - vec3(-e, 0.0, 0.0);
    vec3 pz = vec3(0.0, 0.0, e) + displacementAt(inPatch + vec2(0.0, e)) -
              displacementAt(inPatch - vec2(0.0, e)) - vec3(0.0, 0.0, -e);
    vec3 n = normalize(cross(pz, px));
    vec3 v = normalize(pelicanFrame.camera_position.xyz - inWorld);
    float fresnel = 0.02 + 0.98 * pow(1.0 - max(dot(n, v), 0.0), 5.0);
    vec3 r = reflect(-v, n);
    r.y = abs(r.y);
    vec3 color = mix(DEEP + vec3(0.0, 0.05, 0.05) * max(dot(n, SUN), 0.0), sky(r), fresnel);
    outColor = vec4(color, 1.0);
}

#version 460
#extension GL_GOOGLE_include_directive : require
#include "pelican_sets.glsl"
#include "pelican_view.glsl"
#include "pelican_loop.glsl"

// GB-3 A / LC-1s: one radix-2 Stockham stage of the inverse 2D FFT (the
// loop's body). The stage is the loop's element, read with
// pelican_loop_element(): one body, one shader, 2 * log2(N) copies.
// Stages 0..7 run along x, 8..15 along y, for N = 256. Each texel holds two
// complex values (rg, ba) transformed together; twiddles are computed here.

layout(location = 0) in vec2 inUV;
layout(location = 0) out vec4 outColor;

PELICAN_DECLARE_INPUT_0(source);

#if PELICAN_INPUT_0_LAYERED
#define FETCH0(p) texelFetch(source, ivec3((p), 0), 0)
#else
#define FETCH0(p) texelFetch(source, (p), 0)
#endif

const float PI = 3.14159265358979;

vec2 cmul(vec2 a, vec2 b) { return vec2(a.x * b.x - a.y * b.y, a.x * b.y + a.y * b.x); }

void main() {
    const int n = 256;
    const int bits = 8;
    ivec2 p = ivec2(gl_FragCoord.xy);
    int stage = int(pelican_loop_element());
    bool vertical = stage >= bits;
    int ns = 1 << (vertical ? stage - bits : stage);
    int o = vertical ? p.y : p.x;
    int r = o % (2 * ns);
    int jm = r % ns;
    int j = (o / (2 * ns)) * ns + jm;
    ivec2 i0 = vertical ? ivec2(p.x, j) : ivec2(j, p.y);
    ivec2 i1 = vertical ? ivec2(p.x, j + n / 2) : ivec2(j + n / 2, p.y);
    vec4 a0 = FETCH0(i0);
    vec4 a1 = FETCH0(i1);
    float angle = PI * float(jm) / float(ns);   // +2 pi jm / (2 ns): the inverse
    vec2 w = vec2(cos(angle), sin(angle));
    vec4 t = vec4(cmul(w, a1.xy), cmul(w, a1.zw));
    outColor = r < ns ? a0 + t : a0 - t;
}
